#include "what_changed/model.hpp"
#include <algorithm>
#include <set>

namespace wc {
namespace {std::string bounded_string(const Json&j,const char*name,std::size_t max=4096){auto&s=j.as_string();if(s.size()>max)throw JsonError(std::string(name)+" too large");return s;}void exact_keys(const Json::Object&o,const std::set<std::string>&allowed){const auto unknown=std::find_if(o.begin(),o.end(),[&allowed](const auto&kv){return allowed.count(kv.first)==0;});if(unknown!=o.end())throw JsonError("unknown field: "+unknown->first);}}
Json snapshot_to_json(const Snapshot&s){Json::Object cats;for(const auto&ck:s.categories){Json::Object entries;for(const auto&e:ck.second.entries)entries.emplace(e.first,e.second);cats.emplace(ck.first,Json::Object{{"entries",Json(std::move(entries))},{"note",ck.second.note},{"status",ck.second.status}});}return Json::Object{{"application_version",s.application_version},{"capture_metadata",Json::Object{{"captured_at",s.captured_at},{"privacy_profile","default"},{"semantic_comparison_excludes",Json::Array{Json("captured_at")}}}},{"categories",Json(std::move(cats))},{"schema_version",static_cast<std::int64_t>(s.schema_version)}};}
Snapshot snapshot_from_json(const Json&j){const auto&o=j.as_object();exact_keys(o,{"schema_version","application_version","capture_metadata","categories"});Snapshot s;auto ver=j.at("schema_version").as_int();if(ver!=1)throw JsonError(ver>1?"unsupported future schema version":"invalid schema version");s.schema_version=static_cast<int>(ver);s.application_version=bounded_string(j.at("application_version"),"application_version",64);const auto&m=j.at("capture_metadata").as_object();if(m.size()>16)throw JsonError("too many metadata fields");s.captured_at=bounded_string(j.at("capture_metadata").at("captured_at"),"captured_at",64);const auto&cats=j.at("categories").as_object();if(cats.size()>64)throw JsonError("too many categories");for(const auto&ck:cats){if(ck.first.size()>64)throw JsonError("category key too large");const auto&co=ck.second.as_object();exact_keys(co,{"status","note","entries"});Category c;c.status=bounded_string(ck.second.at("status"),"status",32);if(c.status!="ok"&&c.status!="partial"&&c.status!="unavailable")throw JsonError("invalid category status");c.note=bounded_string(ck.second.at("note"),"note",4096);const auto&es=ck.second.at("entries").as_object();if(es.size()>200000)throw JsonError("too many entries");for(const auto&e:es){if(e.first.empty()||e.first.size()>4096)throw JsonError("invalid entry key");c.entries.emplace(e.first,e.second);}s.categories.emplace(ck.first,std::move(c));}return s;}
std::string serialize_snapshot(const Snapshot&s,bool pretty){return snapshot_to_json(s).dump(pretty)+"\n";}
Snapshot parse_snapshot(const std::string&s){return snapshot_from_json(Json::parse(s));}
}
